# Let's trace paths to verify depth 4
def get_nodes_at_depth(graph, start, target_depth):
    """Helper to show the BFS levels"""
    from collections import deque
    visited = {start: 0}
    queue = deque([start])
    levels = {0: {start}}

    while queue:
        current = queue.popleft()
        current_depth = visited[current]

        if current_depth >= target_depth:
            continue

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                visited[neighbor] = current_depth + 1
                if current_depth + 1 not in levels:
                    levels[current_depth + 1] = set()
                levels[current_depth + 1].add(neighbor)
                queue.append(neighbor)

    return levels

levels = get_nodes_at_depth(graph, start, 4)
for d in range(5):
    print(f"Depth {d}: {len(levels.get(d, set()))} nodes")

